const ICONS={map:'<rect x="3" y="3" width="18" height="6" rx="2"/><path d="M12 9v4M5 13h14M5 13v3m14-3v3"/><rect x="2" y="16" width="6" height="5" rx="1"/><rect x="16" y="16" width="6" height="5" rx="1"/>',check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 12 3 3 5-6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18M8 15h2m4 0h2"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8m-8 4h6"/>',send:'<path d="m3 3 19 9-19 9 4-9zM7 12h15"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 4v3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const statusClass=s=>/완료|확정|확인$|유지/.test(s)&&!s.includes('계약')?'green':/전|계약|지원|반송/.test(s)?'amber':'neutral';
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
document.querySelector('#admin-top').href=LINKS.admin;
const KEY='siriai-and2ble-operations-v1';
let saved={};let storageFailed=false;
try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};}catch{saved={};storageFailed=true;}
const doneFor=i=>saved[i.id]?.revision===(i.revision||2)?!!saved[i.id].done:!!i.resolved;
let currentFilter='all',toastTimer,lastDialogTrigger;
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{storageFailed=true;notify('브라우저 저장이 차단되어 있어요. 내보내기로 기록을 보관하세요.');}}
function renderMap(){
 document.querySelector('#root-node').innerHTML=`<div class="root-wrap"><button class="root-card" data-node="control"><span class="node-kicker">AND2BLE · French Kissing</span><span class="root-arrow" aria-hidden="true">↗</span><h3>SIRIAI 캠페인 운영</h3><span class="chip">모집 진행 중</span><p>목표 180건 · 게시 안내 11.09–11.15</p></button></div>`;
 document.querySelector('#branches').innerHTML=BRANCHES.map(b=>{const n=NODES[b.id];return `<article class="branch"><div class="branch-card"><button class="node-main" data-node="${b.id}"><div class="branch-top"><span class="branch-symbol">${icon(b.icon)}</span><span class="chip ${statusClass(n.status)}">${n.status}</span></div><h3>${n.title}</h3><p class="node-desc">${n.summary}</p><div class="node-bottom"><span>${b.children.length}개 연결 업무</span><span>상세 ↗</span></div></button><button class="branch-toggle" data-branch="${b.id}" aria-expanded="true" aria-controls="children-${b.id}">하위 업무 접기 −</button></div><div class="children" id="children-${b.id}">${b.children.map(id=>`<button class="leaf" data-node="${id}"><span class="leaf-arrow" aria-hidden="true">↗</span><strong>${NODES[id].title}</strong><span class="chip ${statusClass(NODES[id].status)}">${NODES[id].status}</span></button>`).join('')}</div></article>`}).join('');
}
function openNode(id,trigger){const n=NODES[id];if(!n)return;lastDialogTrigger=trigger;
 document.querySelector('#detail-content').innerHTML=`<span class="chip ${statusClass(n.status)}">${n.status}</span><h2 id="detail-title">${n.title}</h2><p class="detail-kicker">${n.role}</p><p class="detail-summary">${n.summary}</p><ul class="detail-facts">${n.facts.map(s=>`<li>${s}</li>`).join('')}</ul>${n.links.length?`<h3 class="drawer-section">연결된 운영 자료</h3><div class="drawer-links">${n.links.map(([s,u])=>`<a class="button" href="${u}" target="_blank" rel="noopener noreferrer">${s}<span aria-hidden="true">↗</span></a>`).join('')}</div>`:''}<h3 class="drawer-section">관련 준비 항목</h3>${n.issues.map(id=>{const issue=ISSUES.find(i=>i.id===id);return `<button class="drawer-issue" data-issue-jump="${id}"><span class="chip ${doneFor(issue)?'green':'amber'}">${issue.priority}</span><span>${issue.title}</span><span aria-hidden="true">↗</span></button>`}).join('')}<p class="drawer-note">11/5 사용자 확인·담당 배정·최종 모집 메일 팀 공유 결과를 반영했습니다.</p>`;
 document.querySelector('#detail-dialog').showModal();
}
const dialog=document.querySelector('#detail-dialog');
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>lastDialogTrigger?.focus({preventScroll:true}));
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right)dialog.close();}});
function renderChecks(){
 const list=ISSUES.filter(i=>currentFilter==='all'||(currentFilter==='pending'&&!doneFor(i))||(currentFilter==='done'&&doneFor(i))||i.priority===currentFilter);
 const done=ISSUES.filter(i=>doneFor(i)).length;
 document.querySelector('[data-filter="all"]').textContent=`전체 ${ISSUES.length}`;
 document.querySelector('.nav-item .count').textContent=ISSUES.length-done;
 document.querySelector('#check-progress').textContent=`${done} / ${ISSUES.length} 항목 확인 완료`;
 document.querySelector('#issue-list').innerHTML=list.length?list.map(i=>`<article class="issue ${doneFor(i)?'done':''}" id="issue-${i.id}"><div class="issue-head"><input class="issue-check" type="checkbox" data-check="${i.id}" id="check-${i.id}" aria-label="${i.title} 완료" ${doneFor(i)?'checked':''}><div class="issue-content"><div class="issue-title"><span class="chip ${doneFor(i)?'green':'amber'}">${i.priority}</span><h3><label for="check-${i.id}">${i.title}</label></h3></div><p>${i.owner}</p></div></div><details><summary>확인 근거와 조치 보기</summary><div class="issue-body"><h4>확인한 내용</h4><p>${i.finding}</p><h4>다음 조치</h4><p class="action">${i.action}</p><div class="evidence">근거 · ${i.evidence}</div><div class="link-row">${i.links.map(([s,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${s} ↗</a>`).join('')}</div><label class="note-label" for="note-${i.id}">담당자 · 결정 사항 · 확인 근거</label><textarea id="note-${i.id}" data-note="${i.id}" placeholder="예: 담당자 / 확정 내용 / 근거 링크">${esc(saved[i.id]?.note||'')}</textarea></div></details></article>`).join(''):'<div class="empty">이 조건에 해당하는 항목이 없습니다.</div>';
}
const RESOURCES=[
 ['발송 준비 시트','기존 참여자 91명 메일 발송 · 반송 1건 후속','Google Sheets · 11/5 조회',LINKS.sheet],
 ['신규 DM 발송 시트','정시예 419명 · 조준석 419명 · 김소현 418명','발송·응대 착수 · 1,256명 배정',LINKS.dm],
 ['챌린지 운영 어드민','신청·선정·업로드·검수·지급 상태의 원본 도구','11/5 화면 확인 · 실제 상태는 어드민에서',LINKS.admin],
 ['응답 확인 시트','폼 응답 확인 · 테스트 2행은 실적에서 제외','Google Sheets · 선정 상태 대사 필요',LINKS.response],
 ['일본어 가이드 · 신청 폼','크리에이터에게 보내는 모집·참여 페이지','11/9–11/15 · 간단한 모집 안내',LINKS.ja],
 ['한국어 가이드 · 검수용','일본어 페이지와 조건 일치 여부 검수','내부 검수용',LINKS.ko],
 ['선정자 상세 가이드 · 일본어','선정 확정 이후 촬영·게시 기준 안내','11/6 선정 안내 링크 교체',LINKS.selectedJa],
 ['선정자 상세 가이드 · 한국어','일본어 상세 가이드의 내부 검수본','참여자 상세 조건 검수',LINKS.selectedKo],
 ['Instagram 음원 설정 가이드','공식 음원 태그 0% / 원본 소리 100% 안내','선정 한·일 메일 반영 완료',LINKS.ig],
 ['TikTok 공식 음원','French Kissing · 의뢰 및 선정 메일의 링크','링크 대조 완료 · 일본 계정 사용 테스트 필요',LINKS.sound],
 ['의뢰 메일의 자료 폴더','고객사가 처음 제공한 음원·안무 자료 위치','다른 폴더와 내용·공유 권한 대조 필요',LINKS.originalDrive],
 ['선정 메일의 자료 폴더','일본어 선정 메일에 연결된 자료 위치','의뢰 폴더와 ID 다름 · 내용 동일성 미검증',LINKS.mailDrive],
 ['검토 보고서','근거·판단·미확인 범위를 함께 정리한 문서','2026.11.05 작성 · Markdown','review.md']
];
function resourceDownload(url){const key=Object.keys(LINKS).find(k=>LINKS[k]===url);if(url==='review.md')return ['review.md','Markdown ↓'];if(['sheet','dm','response'].includes(key)){const gid=key==='sheet'?'815876664':key==='dm'?'211412208':'1002';return ['https://docs.google.com/spreadsheets/d/1T1i3U-lNK0yE0dv0L_adKKv5OOw5NY-BT8PGSDDyWYU/export?format=csv&gid='+gid,'CSV 다운로드 ↗'];}if(key==='selectedJa'||key==='selectedKo')return ['downloads/guide-selected-'+(key==='selectedJa'?'ja':'ko')+'.html','상세 가이드 HTML ↓'];if(['ja','ko','ig'].includes(key))return ['downloads/guide-'+key+'.html','가이드 HTML ↓'];return ['downloads/'+key+'.url','원본 바로가기 파일 ↓'];}
function renderResources(query=''){const q=query.trim().toLowerCase();const extra=[['선정자 안내 일본어 DM','선정 이메일 발송 후 가이드 확인 안내','일본어 발송용','downloads/dm-selected-ja.txt'],['선정자 안내 한국어 DM','선정 이메일 발송 후 가이드 확인 안내','한국어 검수용','downloads/dm-selected-ko.txt'],['Instagram 전용 일본어 DM','Instagram Reels 모집 발송용','11/9 첨부 원문','downloads/dm-ig-ja.txt'],['Instagram 전용 한국어 DM','내부 검수용','11/9 첨부 원문','downloads/dm-ig-ko.txt'],['기존 통합 일본어 DM','11/5 통합 모집 문안','TXT · 최종본','downloads/dm-ja.txt'],['기존 통합 한국어 DM','내부 확인용 문안','TXT · 최종본','downloads/dm-ko.txt'],['DM 담당 안내','3명별 담당 범위와 시작 링크','단톡방 배분용 TXT','downloads/dm-assignments.txt'],['이메일 발송 준비 안내','HTML·본문 복사·EML 사용법','운영 기준과 단계별 사용 조건','downloads/email-guide.txt'],['운영 일정·기준','게시 일정과 운영 기준표','2026.11.05 기준','downloads/operations.txt']];const rows=[...RESOURCES,...extra].filter(r=>r.slice(0,3).join(' ').toLowerCase().includes(q));document.querySelector('#resource-list').innerHTML=rows.length?rows.map(([title,desc,note,url])=>{const local=url.startsWith('downloads/');const [download,label]=local?[url,'TXT 다운로드 ↓']:resourceDownload(url);return '<article class="resource"><div class="resource-top"><h3>'+esc(title)+'</h3></div><p>'+esc(desc)+'</p><small>'+esc(note)+'</small><div class="dm-actions"><a class="button small" href="'+url+'" target="_blank" rel="noopener noreferrer">원본 보기 ↗</a><a class="button small" href="'+download+'" '+(download.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':'download')+'>'+label+'</a></div>'+(['admin','sound','originalDrive','mailDrive'].some(k=>LINKS[k]===url)?'<p class="resource-help">웹 도구·Drive 폴더는 바로가기 파일을 제공합니다. 실제 자료는 원본에서 권한 확인 후 다운로드하세요.</p>':'')+'</article>';}).join(''):'<div class="empty">검색 결과가 없습니다. 다른 자료 이름을 입력하세요.</div>';}
function showView(){const selectedDm=location.hash==='#selected-dm';let view=location.hash==='#guide-update'?'emails':selectedDm?'dm':location.hash.slice(1)||'map';if(!['map','dm','emails','checks','schedule','resources'].includes(view))view='map';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==`view-${view}`);document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if(selectedDm)document.querySelector('#selected-dm').scrollIntoView();}
document.addEventListener('click',e=>{
 const localLink=e.target.closest('a[href^="#"]');if(localLink&&dialog.open)dialog.close();
 const copy=e.target.closest('[data-copy]');if(copy)copyDmText(copy.dataset.copy);
 const node=e.target.closest('[data-node]');if(node)openNode(node.dataset.node,node);
 const toggle=e.target.closest('[data-branch]');if(toggle){const expanded=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!expanded));toggle.textContent=expanded?'하위 업무 펼치기 +':'하위 업무 접기 −';document.querySelector(`#children-${toggle.dataset.branch}`).hidden=expanded;}
 const filter=e.target.closest('[data-filter]');if(filter){currentFilter=filter.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',String(b===filter))});renderChecks();}
 const jump=e.target.closest('[data-issue-jump]');if(jump){const id=jump.dataset.issueJump;dialog.close();currentFilter='all';document.querySelector('[data-filter="all"]').click();location.hash='checks';showView();const article=document.querySelector(`#issue-${id}`);article.querySelector('details').open=true;article.scrollIntoView({block:'center',behavior:'instant'});article.querySelector('summary').focus({preventScroll:true});}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-check]')){const id=e.target.dataset.check;saved[id]={...(saved[id]||{}),done:e.target.checked,revision:ISSUES.find(i=>i.id===id).revision||2,updatedAt:new Date().toISOString()};persist();e.target.closest('.issue').classList.toggle('done',e.target.checked);document.querySelector('#check-progress').textContent=`${ISSUES.filter(i=>doneFor(i)).length} / ${ISSUES.length} 항목 확인 완료`;if(currentFilter==='done'||currentFilter==='pending')renderChecks();}});
document.addEventListener('input',e=>{if(e.target.matches('[data-note]')){const id=e.target.dataset.note;saved[id]={...(saved[id]||{}),note:e.target.value,updatedAt:new Date().toISOString()};persist();}});
document.querySelector('#resource-search').addEventListener('input',e=>renderResources(e.target.value));
document.querySelector('#toggle-details').addEventListener('click',e=>{const compact=document.querySelector('#org-chart').classList.toggle('compact');e.currentTarget.setAttribute('aria-pressed',String(compact));e.currentTarget.textContent=compact?'자세히 보기':'간단히 보기';});
document.querySelector('#expand-all').addEventListener('click',()=>document.querySelectorAll('[data-branch][aria-expanded="false"]').forEach(b=>b.click()));
document.querySelector('#export-checks').addEventListener('click',()=>{const content=['# AND2BLE 운영 점검 기록','',`내보낸 시각: ${new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})} (KST)`,`자료 검토 기준: 2026.11.05 사용자 답변 반영 · 체크·메모는 브라우저 개인 기록`,'',...ISSUES.flatMap(i=>[`## ${doneFor(i)?'[완료]':'[미완료]'} ${i.title}`,`- 단계: ${i.priority}`,`- 담당 역할: ${i.owner}`,`- 확인 내용: ${i.finding}`,`- 조치: ${i.action}`,`- 근거: ${i.evidence}`,`- 메모: ${saved[i.id]?.note||'없음'}`,''])].join('\n');const url=URL.createObjectURL(new Blob([content],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='AND2BLE-운영점검.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('현재 점검 기록을 내보냈습니다.');});
window.addEventListener('hashchange',showView);
renderMap();renderChecks();renderResources();showView();if(storageFailed)notify('저장된 기록을 읽지 못했습니다. 내보내기로 기록을 보관하세요.');

function assignmentMessage(a){return '['+a.name+'님 DM 발송 담당]\n담당 범위: '+a.start+'~'+a.end+'행 / '+a.count+'명\n시작 링크:\n'+a.url;}
function dmText(key){if(key==='all')return DM_ASSIGNMENTS.map(assignmentMessage).join('\n\n');if(Object.hasOwn(DM_COPY,key))return DM_COPY[key];return assignmentMessage(DM_ASSIGNMENTS[Number(key)]);}
async function copyDmText(key){const text=dmText(key);try{await navigator.clipboard.writeText(text);notify('내용을 복사했습니다.');}catch{const fallback=document.querySelector('#copy-fallback');fallback.hidden=false;fallback.value=text;fallback.focus();fallback.select();notify('자동 복사가 차단됐습니다. 선택된 내용을 직접 복사하세요.');}}
function renderDm(){document.querySelector('#dm-assignments').innerHTML=DM_ASSIGNMENTS.map((a,i)=>'<article class="dm-card"><h3>'+a.name+'</h3><p>'+a.start+'~'+a.end+'행 · '+a.count+'명</p><div class="dm-actions"><a class="button" href="'+a.url+'" target="_blank" rel="noopener noreferrer">시작행 열기 ↗</a><button class="button accent" data-copy="'+i+'" aria-label="'+a.name+' 담당 안내 복사">담당 안내 복사</button></div></article>').join('');document.querySelector('#dm-ja').textContent=DM_COPY.ja;document.querySelector('#dm-ko').textContent=DM_COPY.ko;for(const key of ['ig-ja','ig-ko','selected-ja','selected-ko'])document.querySelector('#dm-'+key).textContent=DM_COPY[key];}
renderDm();

document.addEventListener('click',async e=>{if(!e.target.closest('[data-copy-referral]'))return;const field=document.querySelector('#public-referral-url');try{await navigator.clipboard.writeText(field.value);notify('일본어 친구추천 링크를 복사했습니다.');}catch{field.focus();field.select();notify('선택된 링크를 직접 복사해 주세요.');}});
